(
  'alabama-hills-movie-road',
  'Alabama Hills designated sites on Movie Road',
  extensions.st_setsrid(extensions.st_makepoint(-118.11244, 36.62084), 4326)::extensions.geography,
  'dispersed',
  'BLM · Bishop Field Office (Alabama Hills National Scenic Area)',
