  '[{"label":"BLM: Gold Butte National Monument","url":"https://www.blm.gov/visit/gold-butte-national-monument"},{"label":"Campendium: Whitney Pocket","url":"https://maps.campendium.com/us/bunkerville-nv/points-of-interest/whitney-pocket"},{"label":"Bird & Hike: Whitney Pocket campsites","url":"https://t.birdandhike.com/Hike/GoldButte/Campsites/WP-camps/_WP-camps.htm"},{"label":"Roadtrip Ryan: Whitney Pocket","url":"https://www.roadtripryan.com/go/t/nevada/southern-nevada/whitney-pocket"}]'::jsonb,
