  '[{"label":"Campendium: Nip & Tuck Road Dispersed Camping","url":"https://maps.campendium.com/us/stanley-id/nature/nip-tuck-road-dispersed-camping"},{"label":"The Dyrt: Nip and Tuck Rd Dispersed Camping","url":"https://www.thedyrt.com/camping/idaho/dispersed-camping-on-nip-and-tuck-rd-near-stanley-idaho"},{"label":"Forest Service: Sawtooth NRA occupancy and use order (2020)","url":"https://fs.usda.gov/Internet/FSE_DOCUMENTS/fseprd852025.pdf"},{"label":"Forest Service: Sawtooth NRA dispersed camping rules","url":"https://fs.usda.gov/Internet/FSE_DOCUMENTS/fseprd547101.pdf"},{"label":"KMVT: Sawtooth National Forest camping rule changes","url":"https://www.kmvt.com/2021/04/12/sawtooth-national-forest-camping-rule-changes"}]'::jsonb,
