  1,
  '2wd-ok',
  'Right on US-20 (Targhee Pass Highway). Some sites are gravel and a bit uneven',
  false,
  true,
  true,
  true,
  77,
  true,
  true,
  null,
  null,
  array['electric', 'water', 'sewer']::text[],
  'reservable',
  'Prices vary by date and site; check koa.com. Campers reported paying $151 to $165 a night for RV sites in summer 2024. Open May 19 to Oct. 1, with fewer services in fall.',
  array['Heated indoor pool (summer)', 'Wi-Fi', 'Cable TV', 'Laundry', 'Camp store', 'Dog park', 'Propane', 'Firewood', 'Café and coffee cabin', 'Bike rentals', 'Playground', 'Yellowstone tour pickups']::text[],
  array['RV and tent sites: check-in 1:00 p.m., check-out 11:00 a.m.', 'Cabins: check-in 3:00 p.m., check-out 11:00 a.m.', 'Pets welcome at pet-friendly sites; see KOA pet policy']::text[],
  'On US-20 about 6 miles west of Yellowstone’s West Entrance, at 3305 Targhee Pass Highway. From Idaho it is about 3 miles east of the state line. The Mountainside KOA is 1.5 miles farther west; don’t mix them up.',
  '(406) 646-7606',
  '[{"label":"KOA: Yellowstone Park / West Gate KOA Holiday","url":"https://koa.com/campgrounds/yellowstone-park/"},{"label":"Campendium: Yellowstone Park - West Gate KOA Holiday","url":"https://maps.campendium.com/us/west-yellowstone-mt/camping-rv/yellowstone-park-west-gate-koa-holiday"}]'::jsonb,
