  85,
  array['electric', 'water', 'sewer']::text[],
  'reservable',
  'Prices vary by date and site; check koa.com. Latest RV price seen: $85 (July 2026). Seasonal: open April 25 to November 2. Some extras cost more (Wi-Fi, mini golf, firewood).',
  array['Showers', 'Laundry', 'Pool (seasonal)', 'Hot tub/sauna', 'Camp store', 'Wi-Fi (paid)', 'Dog park', 'Playground', 'Mini golf', 'Cabins and yurts', 'Dump station']::text[],
  array['RV and tent sites: check in 12 pm, check out 11 am', 'Cabins and yurts: check in 4 pm, check out 11 am', 'Pets allowed under the KOA pet policy']::text[],
  'Don''t follow Google directions, which may send you up Baker Lake Road. From I-5 exit 230, take WA 20 east about 23 miles to Russell Road (just past Baker Lake Road). Turn left and go straight about half a mile to the campground.',
  '(360) 826-3554',
  '[{"label":"KOA: Concrete / Grandy Creek KOA Holiday","url":"https://koa.com/campgrounds/concrete/"},{"label":"Campendium: Concrete-Grandy Creek KOA","url":"https://maps.campendium.com/us/concrete-wa/camping-rv/concrete-grandy-creek-koa-concrete-wa"}]'::jsonb,
