  extensions.st_setsrid(extensions.st_makepoint(-121.7353, 45.28113), 4326)::extensions.geography,
  'dispersed',
  'Mt. Hood National Forest',
  14,
  2,
  '2wd-ok',
  'Paved road to a large, open, dusty gravel airstrip with some rocky ground.',
  null,
  true,
  true,
  true,
  39,
  true,
  true,
  0,
  null,
