  null,
  true,
  true,
  true,
  100,
  true,
  true,
  null,
  60,
  array['electric', 'water', 'sewer']::text[],
  'reservable',
  'Prices vary by date and site; check koa.com. Lowest RV site price seen October 2026: $60. Open all year.',
  array['Showers and restrooms', 'Wi-Fi', 'Cable TV', 'Pool (late April to October 1)', 'Café and camp store', 'Propane', 'Firewood for sale', 'Dog park', 'Playground', 'Pavilion', 'Game room', 'Disc golf', 'Gem mining', 'Hiking trailheads', 'Bear boxes at tent sites', 'Cabins']::text[],
  array['RV and tent sites: check in 1 pm, check out 11 am', 'Cabins: check in 3 pm, check out 11 am', 'Up to 8 people per tent site', 'Read KOA''s pet policy before you bring pets']::text[],
  '4874 Hooper Highway, Cosby, TN 37722, about 17 miles from downtown Gatlinburg. In October 2026 KOA routed campers around a closed section of I-40: take I-40 to exit 435 at Newport, then US 321 toward Gatlinburg. The office is open 24 hours.',
  '(423) 532-7183',
  '[{"label":"KOA: Gatlinburg East / Smoky Mountain KOA Holiday","url":"https://koa.com/campgrounds/gatlinburg/"}]'::jsonb,
  false,
  0
),
(
  'hunter-camp-217a-sam-houston',
  'Hunter Camp 217A, Sam Houston National Forest',
  extensions.st_setsrid(extensions.st_makepoint(-95.12575, 30.48719), 4326)::extensions.geography,
  'dispersed',
  'Sam Houston National Forest · Sam Houston Ranger District',
  14,
  2,
  '2wd-ok',
  'Hard-packed dirt and red sand with potholes and ruts. Muddy after heavy rain',
  null,
  true,
  true,
  true,
  18,
  null,
  null,
  0,
  null,
  '{}'::text[],
  'not-needed',
  'Free. No water, toilets or trash service (a portable toilet near the entrance was reported in 2020).',
  array['Horse and hiking trails nearby', 'Double Lake Recreation Area about 3 miles north']::text[],
  array['Stay up to 14 days in any 30 days', 'Up to 8 people and 2 tents per campsite', 'No gasoline generators from 10 pm to 6 am', 'This is a designated hunter camp: expect hunters during fall and winter hunting seasons', 'Check for burn bans before you light a fire', 'Pack out all trash']::text[],
  'On FS 217A off FM 2666, which connects to FM 2025 north of Cleveland or to US 59 east of Shepherd. About 3 miles south of Double Lake Recreation Area, between Cleveland and Coldspring. Many pull-off sites spread through the trees. Expect some highway noise and horseback riders on the roads.',
  '(936) 344-6205',
  '[{"label":"Campendium: Hunter Camp 217A Dispersed Camping","url":"https://maps.campendium.com/us/cleveland-tx/nature/hunter-camp-217a-dispersed-camping"},{"label":"The Dyrt: Hunter Camp on Forest Road 217A","url":"https://www.thedyrt.com/camping/texas/hunter-camp-on-forest-road-217a"},{"label":"Forest Service: Texas national forests occupancy and use order","url":"https://www.fs.usda.gov/r08/texas/alerts/national-forests-and-grasslands-texas-occupancy-and-use"}]'::jsonb,
  false,
  0
),
(
  'flagpole-knob-george-washington',
  'Flagpole Knob (Forest Road 85)',
  extensions.st_setsrid(extensions.st_makepoint(-79.18396, 38.5101), 4326)::extensions.geography,
  'dispersed',
  'George Washington National Forest · North River Ranger District',
  14,
  4,
  '4wd-required',
  'Narrow, steep, rocky dirt road with deep ruts for about 3.6 miles from Briery Branch Gap',
  null,
  true,
  true,
  null,
  0,
  false,
  null,
  0,
  null,
  '{}'::text[],
  'not-needed',
  'Free dispersed camping. No water, toilets or trash service.',
  array['Grassy summit with views', 'About 5 sites from the woods up to the summit (2020 estimate)']::text[],
  array['Stay up to 14 days in any 30 days', 'Camp within 150 feet of the road and at least 100 feet from streams', 'Use existing fire rings and burn only dead wood on the ground. Check fire restrictions first', 'Pack it in, pack it out', 'Raccoons are bold here: lock up food, trash and shoes']::text[],
  'From Bridgewater, take VA 257 west through Briery Branch and stay on Briery Branch Road (SR 924) past Briery Branch Dam to Briery Branch Gap, where the road ends at a dirt pull-off by FR 85 and FR 25 (about 6.7 miles past the town of Briery Branch). Go north on FR 85 about 3.1 to 3.6 miles to the grassy summit area. If the road is too much for your rig, park at the gap and hike or bike in (7.2 miles round trip).',
  '(540) 432-0187',
  '[{"label":"The Dyrt: Flagpole Knob","url":"https://www.thedyrt.com/camping/virginia/flagpole-knob"},{"label":"Virginia DWR Birding & Wildlife Trail: Flagpole Knob","url":"https://dwr.virginia.gov/vbwt/sites/flagpole-knob"},{"label":"Trails Offroad: Flagpole Knob","url":"https://trailsoffroad.com/trails/2349-flagpole-knob"},{"label":"Forest Service: George Washington and Jefferson camping","url":"https://www.fs.usda.gov/r08/gwj/recreation/camping-cabins"},{"label":"Forest Service: GWJ general prohibitions (14-day limit)","url":"https://www.fs.usda.gov/r08/gwj/alerts/general-prohibitions"}]'::jsonb,
  false,
  0
),
(
  'gandy-creek-dispersed-monongahela',
  'Gandy Creek Dispersed Camping Area',
  extensions.st_setsrid(extensions.st_makepoint(-79.5834, 38.76111), 4326)::extensions.geography,
  'dispersed',
  'Monongahela National Forest · Cheat-Potomac Ranger District',
  14,
  2,
  '2wd-ok',
  'Gravel county road, very dusty when dry. Traffic moves fast around curves',
  null,
  true,
  true,
  true,
  36,
  true,
  null,
  0,
  null,
  '{}'::text[],
  'not-needed',
  'Free, first come, first served (one camper reported a $3 fee in 2023, so check signs). About 17 signed sites. No water or trash service. The vault toilet was closed after a tree damaged it (Aug 2026).',
  array['Fire rings', 'Creekside sites with trout fishing', 'Seneca Creek Backcountry trailheads']::text[],
  array['Camp only at sites marked with a campsite sign', 'No more than 2 vehicles per site', 'Stay up to 14 days within 28 days at one site', 'Don''t leave gear unattended more than 24 hours', 'No hitching saddle or pack animals between Gandy Creek Road, Route 29 and Gandy Creek', 'Pack out all trash']::text[],
  'Along Gandy Creek on Route 29 (Whitmer Road) on the west side of the Seneca Creek Backcountry, between Little Italy and the Forest Road 1 junction, north of Spruce Knob. From the Elkins area, take US 33 to Rich Mountain Road and go 1.7 miles to Job, then follow Route 29 about 15 miles (WVU DIY Outdoors directions). Cell service is weak to none, so download directions first.',
  '(304) 636-1800',
  '[{"label":"Campendium: Gandy Creek Dispersed Camping Area","url":"https://maps.campendium.com/us/whitmer-wv/camping-rv/gandy-creek-dispersed-camping-area"},{"label":"Forest Service: Gandy Creek Dispersed Area order","url":"https://www.fs.usda.gov/r09/monongahela/alerts/gandy-creek-dispersed-area"},{"label":"Forest Service: Monongahela general use restrictions","url":"https://www.fs.usda.gov/r09/monongahela/alerts/general-use-restrictions"},{"label":"Forest Service: Monongahela alerts","url":"https://www.fs.usda.gov/r09/monongahela/alerts"},{"label":"WVU DIY Outdoors: Gandy Creek Dispersed Camping","url":"https://diyoutdoors.wvu.edu/camping/gandy-creek-dispersed-camping"}]'::jsonb,
  false,
  0
)
